static <T> void verifyLifecycle(Session s, T entity, Function<T,Object> idExtractor) {
    if (idExtractor.apply(entity) != null) throw new AssertionError("powinno byc null przed persist");
    s.persist(entity);
    if (idExtractor.apply(entity) == null) throw new AssertionError("powinno byc ustawione po persist");
}

